const app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'PKR '+Number(x).toLocaleString('en-PK');
let roman=localStorage.getItem('dd-language')==='roman',session={},step=1,tab='overview',cart=[],currentStore,products=[],editProduct=null;
let draft={email:sessionStorage.getItem('dd-signup-email')||'',password:'',slug:'',details:{name:'',description:'',category:'Fashion & accessories',whatsapp:'',address:'',logo:'',banner:'',instagram:'',facebook:'',website:'',returns:'',deliveryInfo:'',accent:'#075e47',delivery:200},sections:[{type:'hero',layout:1},{type:'featured',layout:1},{type:'benefits',layout:1},{type:'contact',layout:1}]};
const t=(en,ur)=>roman?ur:en;
const icons={shop:'▦',arrow:'↗',check:'✓',plus:'+',bag:'◧',spark:'✧'};
const sectionNames={hero:'Hero banner',categories:'Shop by category',featured:'Featured products',offers:'Offers & promotions',about:'Our story',reviews:'Customer reviews',benefits:'Store highlights',contact:'Contact & delivery'};
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4500)}
const field=(label,name,value='',type='text',required=false,extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;
const area=(label,name,value='')=>`<label class="field">${esc(label)}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
const brand=`<a class="brand" href="/"><span class="brand-icon">▦</span>digital<span>dukan<span class="brand-dot">.</span></span></a>`;
const dashboardPath=()=>session.user?.role==='admin'?'/admin':'/dashboard';
function nav(){return `<header class="nav">${brand}<nav><a href="/#how">${t('How it works','Kaise kaam karta hai')}</a><a href="/#features">${t('Features','Sahooliyat')}</a><a href="/#pricing">${t('Pricing','Qeemat')}</a></nav><div class="nav-actions"><button class="language" data-action="language">${roman?'English':'Roman Urdu'} <span>⇄</span></button>${session.user?`<a class="login-link" href="${dashboardPath()}">${t(session.user.role==='admin'?'Admin panel':'Dashboard',session.user.role==='admin'?'Admin panel':'Mera dashboard')}</a><button class="btn secondary small" data-action="logout">${t('Sign out','Logout')}</button>`:`<a class="login-link" href="/login">${t('Log in','Login')}</a><a class="btn small" href="/signup">${t('Create your store','Apna store banayein')} ↗</a>`}</div></header>`}
function home(){app.innerHTML=`${nav()}<main><section class="hero"><div class="hero-content"><div class="eyebrow"><span class="status-dot"></span> ${t('BIG DREAMS. YOUR OWN DUKAN.','Barray khwab. Apni dukan.')} </div><h1>${t('Your business.<br>Your store.<br><em>Your next chapter.</em>','Aapka business.<br>Aapka store.<br><em>Aapki nayi shuruat.</em>')}</h1><p class="hero-copy">${t('Turn what you sell into a store you’re proud of. Build your online dukan, share your link, and take orders on WhatsApp. No coding. No complications.','Apne products ka khoobsurat online store banayein. Link share karein aur WhatsApp par orders lein. Coding ki zaroorat nahi.')}</p><form id="home-signup-form" class="home-signup-form"><label class="sr-only" for="home-email">Email address</label><input id="home-email" name="email" type="email" required placeholder="${t('Your email address','Aapka email address')}" autocomplete="email"><button class="btn">${t('Start your free store','Apna free store banayein')} ↗</button></form><div class="hero-buttons"><a href="/demo" class="text-button">${t('Explore a demo store','Demo store dekhein')} <span>→</span></a></div><div class="hero-note"><span>✓ ${t('Free to start','Shuruat bilkul free')}</span><span>✓ ${t('No credit card','Card ki zaroorat nahi')}</span><span>✓ ${t('Made for Pakistan','Pakistan ke liye')}</span></div></div><div class="hero-art"><div class="floating-top"><span class="round-icon">✦</span><div><b>${t('Your brand. Your space.','Aapka brand. Aapki jagah.')}</b><small>${t('A little idea. A big beginning.','Chhota idea. Bari shuruat.')}</small></div></div><div class="mock-browser"><div class="browser-top"><span>● ● ●</span><span>noor-living.digitaldukan.store <span>⌑</span></span></div><div class="mock-nav"><b>NOOR<span> LIVING</span></b><small>Home &nbsp; Shop &nbsp; Our story &nbsp; ♧</small></div><div class="mock-hero"><div><span class="mini-label">THOUGHTFULLY MADE, EVERYDAY.</span><h2>Little things.<br>Lovely living.</h2><p>Make room for things that feel like home.</p><span class="mock-button">Explore collection ↗</span></div><div class="vase-scene"><div class="leaf l1"></div><div class="leaf l2"></div><div class="leaf l3"></div><div class="stem"></div><div class="vase"></div><div class="vase small-vase"></div></div></div><div class="mock-products"><div><div class="product-art bowl"><span></span></div><b>Everyday ceramics</b><small>PKR 2,400</small></div><div><div class="product-art fabric"><span></span></div><b>Soft linen essentials</b><small>PKR 3,200</small></div><div><div class="product-art candle"><span></span></div><b>A moment of calm</b><small>PKR 1,800</small></div></div></div><div class="floating-order"><span class="round-icon">✓</span><div><b>${t('A new order. A new possibility.','Naya order. Naya mauqa.')}</b><small>${t('Straight to your WhatsApp','Seedha aapke WhatsApp par')}</small></div><span class="green-dot"></span></div><span class="art-caption">${t('YOUR STORE COULD BE NEXT ↗','AGLA STORE AAPKA HO SAKTA HAI ↗')}</span></div></section><section class="trust-strip"><span>${t('Everything your small business needs to grow online.','Aapke business ko online barhane ki sahooliyat.')}</span><b>◉ WhatsApp orders</b><b>▦ Your own storefront</b><b>↗ No code needed</b><b>₨ Cash on delivery</b></section><section class="section" id="how"><div class="section-title"><div><div class="eyebrow">${t('FROM IDEA TO OPEN FOR BUSINESS','IDEA SE ONLINE BUSINESS TAK')}</div><h2>${t('Three steps. One fresh start.','Teen steps. Ek nayi shuruat.')}</h2></div><p>${t('You bring the products.<br>We’ll bring the possibilities.','Products aapke.<br>Sahooliyat hamari.')}</p></div><div class="steps"><article><span class="step-no">01</span><div class="step-icon">▤</div><h3>${t('Make it yours','Apna banayein')}</h3><p>${t('Tell us about your business, choose your store name, and pick the sections that tell your story.','Business ki details dein, store ka naam rakhein aur sections choose karein.')}</p></article><article><span class="step-no">02</span><div class="step-icon">▦</div><h3>${t('Fill your shelves','Products shamil karein')}</h3><p>${t('Add products, set your prices, and personalize your store. Your dashboard keeps it all simple.','Products aur prices add karein. Dashboard se store apni pasand ka banayein.')}</p></article><article><span class="step-no">03</span><div class="step-icon">↗</div><h3>${t('Open your doors','Apni dukan kholein')}</h3><p>${t('Once approved, share your store link. Customers add to cart and send their orders on WhatsApp.','Approval ke baad link share karein. Customers cart se WhatsApp orders bhejein.')}</p></article></div></section><section class="feature-band" id="features"><div><div class="eyebrow">${t('BUILT AROUND YOUR BUSINESS','AAPKE BUSINESS KE LIYE')}</div><h2>${t('Small business.<br>Big-store energy.','Chhota business.<br>Bari pehchaan.')}</h2><p>${t('Everything in one place, so you can spend more time doing what you love.','Sab ek jagah, taake aap apne business par tawajjo dein.')}</p><a href="/signup" class="text-button">${t('Let’s build your dukan','Apni dukan banayein')} →</a></div><div class="feature-grid">${[['▦','A storefront that feels like you','Mix and match ready-made sections. Edit whenever inspiration strikes.'],['◉','Orders on WhatsApp','A familiar way to connect. Cart, customer details, and delivery charges included.'],['▤','One simple dashboard','Products, stock, orders, and your store design, neatly together.'],['↗','Your own store address','A memorable link for your brand. Ready to share once approved.']].map(([i,h,p])=>`<article><span>${i}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="section pricing" id="pricing"><div><div class="eyebrow">${t('A GOOD PLACE TO BEGIN','SHURUAT KA BEHTAREEN MAUQA')}</div><h2>${t('Your ambition.<br>Without the upfront cost.','Aapke khwab.<br>Bina shuruati kharch ke.')}</h2><p>${t('Start with our free subscription. Build your store at your pace, and let your business take the next step.','Free subscription se shuru karein. Apni raftaar se store banayein aur business barhayein.')}</p></div><article class="price-card"><div class="price-top"><b>Starter</b><span class="badge">FREE TO START</span></div><h3>PKR <strong>0</strong><small> / active free plan</small></h3><p>One store. Everything you need to begin.</p><ul><li>✓ Your own online storefront</li><li>✓ Customizable sections & layouts</li><li>✓ Product and order management</li><li>✓ WhatsApp checkout & cash on delivery</li><li>✓ No credit card or monthly renewal</li></ul><a class="btn" href="/signup">${t('Create your free store','Apna free store banayein')} ↗</a></article></section><section class="closing"><span>✧</span><h2>${t('Your next customer is online.<br>Let’s get your dukan there.','Aapka agla customer online hai.<br>Apni dukan bhi online laayein.')}</h2><a href="/signup" class="btn light">${t('Start something yours','Apni shuruat karein')} ↗</a></section></main><footer>${brand}<p>${t('A little idea. A big beginning.','Chhota idea. Bari shuruat.')}</p><span>© ${new Date().getFullYear()} Digital Dukan</span></footer>`;if(session.user){document.querySelector('#home-signup-form').outerHTML=`<div class="hero-account"><p class="muted">${t('You’re already signed in. Your workspace is ready.','Aap logged in hain. Apna dashboard kholein.')}</p><a class="btn" href="${dashboardPath()}">${t(session.user.role==='admin'?'Open admin panel':'Go to dashboard',session.user.role==='admin'?'Admin panel kholein':'Dashboard kholein')} ↗</a></div>`;document.querySelectorAll('a[href="/signup"]').forEach(a=>{a.href=dashboardPath();a.textContent=t('Open your workspace →','Apna dashboard kholein →')});}}
function loginPage(){app.innerHTML=`${nav()}<main class="auth-page"><div class="auth-intro"><div class="eyebrow">WELCOME BACK</div><h1>Your dukan.<br>Right where<br><em>you left it.</em></h1><p>Sign in to manage your store, your products, and your next chapter.</p></div><form id="login-form" class="panel auth-card"><h2>Sign in</h2><p class="muted">Store owners and admins sign in here.</p>${field('Email address','email','','email',true)}${field('Password','password','','password',true)}<button class="btn full">Sign in →</button><p class="muted">New here? <a href="/signup">Create your free store</a></p><div class="form-error" role="alert"></div></form></main>`}
function detailsFields(d){return `<div class="form-grid">${field('Store name','name',d.name,'text',true,'maxlength="100"')}${field('WhatsApp number (with country code)','whatsapp',d.whatsapp,'tel',true,'placeholder="923001234567"')}<label class="field">Business category<select name="category">${['Fashion & accessories','Home & living','Beauty & care','Food & groceries','Electronics','Handmade & gifts','Other'].map(c=>`<option ${d.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('Fixed delivery charges (PKR)','delivery',d.delivery,'number',true,'min="0" max="100000"')}${field('Logo image URL (optional)','logo',d.logo,'text',false,'placeholder="https://…"')}${field('Banner image URL (optional)','banner',d.banner,'text',false,'placeholder="https://…"')}${field('Brand color','accent',d.accent||'#075e47','color')}${field('Instagram URL (optional)','instagram',d.instagram,'text',false,'inputmode="url" placeholder="instagram.com/yourname"')}${field('Facebook URL (optional)','facebook',d.facebook,'text',false,'inputmode="url" placeholder="facebook.com/yourpage"')}${field('Website URL (optional)','website',d.website,'text',false,'inputmode="url" placeholder="yourwebsite.com"')}</div>${area('About your store','description',d.description)}${area('Business address','address',d.address)}${area('Delivery information','deliveryInfo',d.deliveryInfo)}${area('Returns & exchange policy','returns',d.returns)}<p class="muted">Social links can be entered without https://; we add it automatically. Image links should be public HTTPS URLs. Leave optional fields blank if you’re not ready.</p>`}
const layoutNames={
  hero:['Text & image','Centered banner','Image first'],
  categories:['Horizontal tiles','Centered tiles','Two-column tiles'],
  featured:['Three columns','Two columns','Four columns'],
  offers:['Classic offer','Centered offer','Accent border'],
  about:['Classic story','Centered story','Accent border'],
  reviews:['Classic feedback','Centered panel','Accent border'],
  benefits:['Three columns','Soft background','Stacked highlights'],
  contact:['Two columns','Centered stack','Soft panel']
};
const sampleProducts=['Ceramic bowl','Linen essentials','Scented candle','Everyday vase'].map((name,i)=>({id:'preview-'+i,details:{name,price:1800+i*400,salePrice:null,stock:null,images:[],category:['Ceramics','Linen','Candles','Home'][i],description:'Thoughtfully made for your everyday.',sizes:'',colors:''}}));
function layoutMarkup(type,layout){
  const existing=session.store?.details||draft.details;
  const details={...existing,name:existing.name||'Your store',description:existing.description||'Beautiful products. A store that feels like you.',deliveryInfo:existing.deliveryInfo||'Delivered across Pakistan.',address:existing.address||'Your business address',whatsapp:existing.whatsapp||'923001234567',delivery:Number(existing.delivery)||200};
  const content=(session.store?.sections||draft.sections).find(x=>x.type===type)||{};
  return renderSection({...content,type,layout},details,sampleProducts);
}
function previewCanvas(type,layout,large=false){return `<div class="layout-preview ${large?'large-layout-preview':''}" aria-hidden="true" inert><div class="preview-canvas storefront">${layoutMarkup(type,layout)}</div></div>`;}
function sectionPicker(list){return `<div class="section-picker">${Object.entries(sectionNames).map(([type,name])=>{const selected=list.find(s=>s.type===type);return `<article class="section-option ${selected?'selected':''}" data-section-type="${type}"><label class="section-toggle"><input type="checkbox" name="section-${type}" ${selected?'checked':''}><b>${name}</b></label><div class="layout-options">${[1,2,3].map(n=>`<div class="layout-choice"><label class="layout-tile"><input type="radio" name="layout-${type}" value="${n}" ${(selected?.layout||1)===n?'checked':''} aria-label="${name}: ${layoutNames[type][n-1]}">${previewCanvas(type,n)}<span class="layout-caption"><b>${layoutNames[type][n-1]}</b><small>Layout ${n}<span class="layout-selected"> · ✓ Selected</span></small></span></label><button type="button" class="layout-expand" data-preview-section="${type}" data-preview-layout="${n}">View larger ↗</button></div>`).join('')}</div></article>`}).join('')}</div>`;}
const previewResize=new ResizeObserver(entries=>{for(const {target} of entries){const canvas=target.querySelector('.preview-canvas');if(!canvas)continue;const scale=target.clientWidth/1200;canvas.style.transform=`scale(${scale})`;target.style.height=Math.ceil(canvas.offsetHeight*scale)+'px';}});
function resizePreviews(){document.querySelectorAll('.layout-preview').forEach(el=>previewResize.observe(el));}
const previewMutations=new MutationObserver(records=>{for(const record of records){for(const node of record.removedNodes)if(node.nodeType===1){if(node.matches('.layout-preview'))previewResize.unobserve(node);node.querySelectorAll('.layout-preview').forEach(el=>previewResize.unobserve(el));}}resizePreviews();});
previewMutations.observe(document.body,{childList:true,subtree:true});
function openLayoutPreview(type,layout){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="panel modal layout-modal" role="dialog" aria-modal="true" aria-label="${sectionNames[type]} preview"><div class="panel-heading"><div><h2>${sectionNames[type]}</h2><p class="muted">${layoutNames[type][layout-1]} · Layout ${layout}</p></div><button type="button" data-action="close-modal" class="icon-btn" aria-label="Close preview">×</button></div>${previewCanvas(type,layout,true)}<p class="muted">Preview uses sample products and your store details. Your products will appear when you add them.</p><button type="button" class="btn full" data-use-layout="${type}" data-layout="${layout}">Use this layout ✓</button></div></div>`);}

function readSections(form){return Object.keys(sectionNames).filter(k=>form.querySelector(`[name="section-${k}"]`).checked).map(k=>({type:k,layout:Number(form.querySelector(`[name="layout-${k}"]:checked`).value)}));}
function signup(){app.innerHTML=`${nav()}<main class="onboard"><div class="onboard-top"><span class="eyebrow">YOUR BUSINESS STARTS HERE</span><h1>Let’s make it <em>yours.</em></h1><p>Create your free store, one simple step at a time.</p></div><div class="progress">${['Your account','Store details','Choose sections','Free subscription'].map((x,i)=>`<span class="${step===i+1?'active':step>i+1?'done':''}"><b>${step>i+1?'✓':i+1}</b>${x}</span>`).join('')}</div><form id="signup-form" class="panel signup-card"><div class="card-heading"><span>0${step} / 04</span><h2>${['Create your account','Tell us about your dukan','Build your homepage','A fresh start. On us.'][step-1]}</h2></div>${step===1?`${field('Email address','email',draft.email,'email',true)}${field('Password','password',draft.password,'password',true,'minlength="8" maxlength="128" autocomplete="new-password"')}<p class="muted">At least 8 characters. One account, one store.</p>`:step===2?`${field('Choose your store address','slug',draft.slug,'text',true,'pattern="[a-z0-9][a-z0-9-]{2,38}[a-z0-9]" placeholder="your-store-name" minlength="4" maxlength="40"')}<p class="muted">Your temporary address: ${esc(location.origin)}/s/<b id="slug-label">${esc(draft.slug||'your-store-name')}</b>. A custom subdomain can be connected later.</p>${detailsFields(draft.details)}`:step===3?`<p class="muted">Choose your sections and a layout for each. You can change them later in your dashboard.</p>${sectionPicker(draft.sections)}`:`<div class="subscription-box"><span class="badge">STARTER PLAN</span><h2>PKR 0</h2><p>Your free subscription stays active. No card. No monthly renewal.</p><ul><li>✓ One store with customizable sections</li><li>✓ Product management and WhatsApp orders</li><li>✓ Store editor and order dashboard</li></ul></div><div class="notice">Your store will be submitted for approval. You can add products and view your private preview while you wait.</div><label class="check-line"><input type="checkbox" name="subscribed" required> Activate my free subscription and submit my store.</label>`}<div class="form-error" role="alert"></div><div class="form-actions">${step>1?'<button type="button" class="btn secondary" data-action="signup-back">← Back</button>':'<a href="/login" class="muted">Already have an account?</a>'}<button class="btn">${step===4?'Subscribe — Free ↗':'Continue →'}</button></div></form></main>`}
function sidebar(){return `<aside class="sidebar">${brand}<div class="workspace-label">STORE WORKSPACE</div>${[['overview','◫','Overview'],['products','▦','Products'],['editor','▤','Store editor'],['orders','◧','Orders'],['settings','⚙','Store details']].map(([k,i,l])=>`<button class="side-link ${tab===k?'active':''}" data-tab="${k}"><span>${i}</span>${l}</button>`).join('')}<div class="sidebar-bottom"><div class="plan-mini"><b>Starter subscription</b><span>PKR 0 · Active</span></div><button class="side-link" data-action="logout">↪ Sign out</button></div></aside>`}
const uploadControl=(target,multiple=false)=>`<label class="upload-control">Upload ${multiple?'product photos':'image'}<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-target="${target}" ${multiple?'multiple':''}></label>`;
async function dashboard(){session=await api('/api/session');if(!session.user){location.href='/login';return}if(session.user.role==='admin'){location.href='/admin';return}const s=session.store;products=await api('/api/products');const orders=await api('/api/orders');app.innerHTML=`<div class="workspace">${sidebar()}<main class="workspace-main"><header class="workspace-header"><div><span class="eyebrow">YOUR DIGITAL DUKAN</span><h1>${tab==='overview'?'Welcome back, '+esc(s.details.name)+'.':({products:'Your products',editor:'Make it yours',orders:'Your orders',settings:'Store details'})[tab]}</h1></div><a class="btn secondary" href="/s/${esc(s.slug)}" target="_blank" rel="noopener">${s.status==='approved'?'View store':'Private preview'} ↗</a></header><div class="store-status ${s.status}"><b>${esc(s.status.toUpperCase())}</b><span>${s.status==='pending'?'Your store is waiting for approval. You can keep building while we review it.':s.status==='approved'?'Your store is live. Every saved change is visible to your customers.':esc(s.reason||'Your store is currently unavailable.')}</span>${s.status==='rejected'?'<button class="btn small" data-action="resubmit">Resubmit for approval</button>':''}</div>${tab==='overview'?`<div class="stats"><article><span>Products on your shelves</span><b>${products.length}</b><small>Ready for your next customer</small></article><article><span>Total orders</span><b>${orders.length}</b><small>${orders.filter(o=>o.status==='New').length} new orders to review</small></article><article><span>Delivered order value</span><b>${money(orders.filter(o=>o.status==='Delivered').reduce((n,o)=>n+o.details.total,0))}</b><small>Cash on delivery</small></article></div><div class="overview-grid"><article class="panel"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>A little progress, every day.</h2><p>Fill your shelves, give your homepage a personal touch, and get ready to share your dukan.</p><div class="quick-actions"><button data-tab="products" class="btn">Add your products +</button><button data-tab="editor" class="btn secondary">Customize store →</button></div></article><article class="panel"><h3>Your store link</h3><p class="store-url">${esc(location.origin)}/s/${esc(s.slug)}</p><button class="btn secondary" data-action="copy-link">Copy link ↗</button><p class="muted">${s.status==='approved'?'Share it with your customers.':'This link is private until your store is approved.'}</p></article></div>`:tab==='products'?productPanel():tab==='orders'?orderPanel(orders):tab==='editor'?`<form id="editor-form" class="panel"><h2>Your homepage sections</h2><p class="muted">Choose sections and layouts. Use the arrows below to change their order.</p><div class="section-order">${s.sections.map((x,i)=>`<div><b>${sectionNames[x.type]}</b><button type="button" data-move="${i}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-direction="1" ${i===s.sections.length-1?'disabled':''}>↓</button></div>`).join('')}</div>${sectionPicker(s.sections)}<h3 style="margin-top:28px">Section content</h3><p class="muted">Optional headings and text. For reviews, enter real customer feedback with their permission.</p>${s.sections.map(x=>`<div class="section-content"><h3>${sectionNames[x.type]}</h3>${field('Custom heading','title-'+x.type,x.title)}${area('Custom text','text-'+x.type,x.text)}</div>`).join('')}<div class="form-error"></div><button class="btn">Save homepage ✓</button></form>`:`<form id="settings-form" class="panel"><h2>Your brand & store information</h2>${detailsFields(s.details)}<div class="form-grid"><div>Store logo${uploadControl('logo')}</div><div>Homepage banner${uploadControl('banner')}</div></div><div class="form-error"></div><button class="btn">Save store details ✓</button></form>`}</main></div>`;}
function productPanel(){return `<div class="panel"><div class="panel-heading"><div><h2>All products <span class="count">${products.length}</span></h2><p class="muted">Your shelves, ready for the world.</p></div><button class="btn" data-action="add-product">+ Add product</button></div>${products.length?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="product-cell">${p.details.images[0]?`<img src="${esc(p.details.images[0])}" alt="">`:'<span class="image-placeholder">▦</span>'}<div><b>${esc(p.details.name)}</b><small>${esc(p.details.category)}</small></div></div></td><td>${money(p.details.salePrice??p.details.price)}</td><td>${p.details.stock??'Not tracked'}</td><td><button class="link-btn" data-edit-product="${p.id}">Edit</button><button class="link-btn danger" data-delete-product="${p.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><span>▦</span><h3>Your shelves are waiting.</h3><p>Add your first product to bring your store to life.</p></div>'}</div>`}
function productModal(p={}){editProduct=p.id||null;const d=p.details||{};document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><form id="product-form" class="panel modal"><div class="panel-heading"><h2>${p.id?'Edit':'Add'} product</h2><button type="button" data-action="close-modal" class="icon-btn">×</button></div>${field('Product name','name',d.name,'text',true)}<div class="form-grid">${field('Price (PKR)','price',d.price,'number',true,'min="1" step="0.01"')}${field('Sale price (optional)','salePrice',d.salePrice,'number',false,'min="1" step="0.01"')}${field('Stock quantity (optional)','stock',d.stock,'number',false,'min="0" step="1"')}${field('Category (optional)','category',d.category)}</div>${area('Product description','description',d.description)}${area('Image URLs — one per line (up to 8)','images',d.images?.join('\n'))}${uploadControl('images',true)}<div class="form-grid">${field('Sizes — comma separated (optional)','sizes',d.sizes,'text',false,'placeholder="S, M, L"')}${field('Colors — comma separated (optional)','colors',d.colors,'text',false,'placeholder="Black, White"')}</div><div class="form-error"></div><button class="btn full">Save product ✓</button></form></div>`)}
function orderPanel(orders){return `<div class="panel"><h2>All orders</h2><p class="muted">Orders are saved before the customer opens WhatsApp. Confirm with your customer before dispatch.</p>${orders.length?orders.map(o=>`<article class="order-card"><div class="panel-heading"><div><b>#${o.id.slice(0,8)}</b><small>${new Date(o.created).toLocaleString()}</small></div><select data-order-status="${o.id}">${['New','Confirmed','Delivered','Cancelled'].map(x=>`<option ${o.status===x?'selected':''}>${x}</option>`).join('')}</select></div><p><b>${esc(o.details.name)}</b> · ${esc(o.details.phone)}<br>${esc(o.details.address)}</p><ul>${o.details.items.map(i=>`<li>${esc(i.name)} ${esc(i.size)} ${esc(i.color)} × ${i.quantity} — ${money(i.price*i.quantity)}</li>`).join('')}</ul><b>${money(o.details.total)}</b><span class="muted"> · Delivery ${money(o.details.delivery)} · Cash on Delivery</span></article>`).join(''):'<div class="empty"><span>◧</span><h3>Your first order is ahead.</h3><p>New orders will appear here.</p></div>'}</div>`}
async function admin(){session=await api('/api/session');if(!session.user){location.href='/login';return}if(session.user.role!=='admin')throw Error('Admin access required.');const stores=await api('/api/admin/stores');app.innerHTML=`<div class="workspace"><aside class="sidebar">${brand}<div class="workspace-label">ADMIN WORKSPACE</div><div class="side-link active">▦ Store approvals</div><div class="sidebar-bottom"><button class="side-link" data-action="logout">↪ Sign out</button></div></aside><main class="workspace-main"><header class="workspace-header"><div><span class="eyebrow">DIGITAL DUKAN ADMIN</span><h1>Good businesses start here.</h1></div><span class="badge">ADMIN PANEL</span></header><div class="stats"><article><span>Waiting for approval</span><b>${stores.filter(s=>s.status==='pending').length}</b></article><article><span>Live stores</span><b>${stores.filter(s=>s.status==='approved').length}</b></article><article><span>Total stores</span><b>${stores.length}</b></article></div><div class="panel"><h2>Store management</h2>${stores.length?stores.map(s=>`<article class="admin-store"><div><h3>${esc(s.details.name)} <span class="badge">${esc(s.status)}</span></h3><p>${esc(s.email)} · /s/${esc(s.slug)}</p><p class="muted">${esc(s.details.description||'No description yet.')}</p>${s.reason?`<p class="muted">Reason: ${esc(s.reason)}</p>`:''}</div><div class="admin-actions"><a href="/s/${esc(s.slug)}" target="_blank" rel="noopener" class="btn secondary small">Preview ↗</a>${s.status!=='approved'?`<button class="btn small" data-admin-id="${s.id}" data-status="approved">${s.status==='suspended'?'Reactivate':'Approve'} ✓</button>`:`<button class="btn secondary small" data-admin-id="${s.id}" data-status="suspended">Suspend</button>`}${['pending','rejected'].includes(s.status)?`<button class="link-btn danger" data-admin-id="${s.id}" data-status="rejected">Reject</button>`:''}</div></article>`).join(''):'<div class="empty"><h3>No stores submitted yet.</h3></div>'}</div></main></div>`}
const demoProducts=[{id:'demo1',details:{name:'Everyday ceramic bowl',price:2400,images:[],category:'Ceramics',stock:null,sizes:'',colors:''}},{id:'demo2',details:{name:'Soft linen essentials',price:3200,images:[],category:'Linen',stock:null,sizes:'',colors:''}},{id:'demo3',details:{name:'A moment of calm',price:1800,images:[],category:'Candles',stock:null,sizes:'',colors:''}}];
async function storefront(slug){const demo=slug==='demo';if(demo){currentStore={slug:'demo',status:'demo',details:{name:'Noor Living',description:'Thoughtfully chosen pieces for a slower, lovelier everyday. Make room for things that feel like home.',delivery:200,accent:'#075e47',deliveryInfo:'Delivered across Pakistan.',returns:'Contact us for returns and exchanges.',whatsapp:''},sections:[{type:'hero',layout:1},{type:'featured',layout:1},{type:'about',layout:1},{type:'benefits',layout:1},{type:'contact',layout:1}]};products=demoProducts}else{const d=await api('/api/public/'+encodeURIComponent(slug));currentStore=d.store;products=d.products}const s=currentStore,d=s.details;cart=[];app.innerHTML=`<div class="storefront" style="--brand:${/^#[a-f0-9]{6}$/i.test(d.accent)?d.accent:'#075e47'}">${s.status!=='approved'?`<div class="preview-notice">${demo?'Demo store · Explore a sample storefront. Checkout is disabled.':'Private preview · Your customers can visit after admin approval.'}</div>`:''}<header class="store-nav"><a href="${demo?'/demo':'/s/'+esc(slug)}" class="store-brand">${d.logo?`<img src="${esc(d.logo)}" alt="">`:''}${esc(d.name)}</a><nav><a href="#store-products">Shop</a><a href="#store-about">Our story</a><button class="btn small" data-action="cart">Cart <span id="cart-count">0</span> ◧</button></nav></header><main>${s.sections.map(x=>renderSection(x,d)).join('')}${!s.sections.some(x=>x.type==='featured')?renderSection({type:'featured',layout:1},d):''}</main><footer><b>${esc(d.name)}</b><span>Powered by <a href="/">Digital Dukan ↗</a></span></footer></div>`}
function renderSection(s,d,items=products){let html=sectionMarkup(s,d,items);if(s.title)html=html.replace(/<(h1|h2)([^>]*)>[\s\S]*?<\/\1>/,(_,tag,attrs)=>`<${tag}${attrs}>${esc(s.title)}</${tag}>`);if(s.text)html=html.replace(/<p([^>]*)>[\s\S]*?<\/p>/,(_,attrs)=>`<p${attrs}>${esc(s.text).replace(/\n/g,'<br>')}</p>`);return html;}
function sectionMarkup(s,d,items=products){const cls=`store-section store-layout-${s.layout}`;if(s.type==='hero')return `<section class="store-hero ${cls}"><div><span class="eyebrow">WELCOME TO ${esc(d.name.toUpperCase())}</span><h1>${esc(d.name)}.<br><em>Made for your everyday.</em></h1><p>${esc(d.description||'Discover our collection, add your favorites to cart, and order on WhatsApp.')}</p><a href="#store-products" class="btn">Explore collection ↗</a></div>${d.banner?`<img class="store-banner" src="${esc(d.banner)}" alt="${esc(d.name)} collection">`:'<div class="store-hero-art"><div class="vase-scene"><div class="leaf l1"></div><div class="leaf l2"></div><div class="stem"></div><div class="vase"></div><div class="vase small-vase"></div></div></div>'}</section>`;if(s.type==='featured')return `<section class="${cls}" id="store-products"><div class="section-title"><div><span class="eyebrow">CHOSEN WITH CARE</span><h2>Find your next favorite.</h2></div><span>${items.length} products</span></div><div class="store-product-grid">${items.length?items.map((p,i)=>{const d=p.details;return `<article class="store-product">${d.images[0]?`<img src="${esc(d.images[0])}" alt="${esc(d.name)}" loading="lazy">`:`<div class="product-art ${['bowl','fabric','candle'][i%3]}"><span></span></div>`}<small>${esc(d.category)}</small><h3>${esc(d.name)}</h3><p>${esc(d.description||'')}</p><b>${money(d.salePrice??d.price)}</b>${d.salePrice?` <del>${money(d.price)}</del>`:''}${d.images.length>1?`<div class="product-thumbnails">${d.images.map(url=>`<img src="${esc(url)}" alt="${esc(d.name)}" loading="lazy">`).join('')}</div>`:''}<div class="variant-selects">${[['sizes','size','Size'],['colors','color','Color']].map(([source,key,label])=>d[source]?`<label>${label}<select id="${key}-${p.id}">${d[source].split(',').map(x=>`<option>${esc(x.trim())}</option>`).join('')}</select></label>`:'').join('')}</div><button class="btn full secondary" data-add-cart="${p.id}" ${d.stock===0?'disabled':''}>${d.stock===0?'Out of stock':'Add to cart +'}</button></article>`}).join(''):'<div class="empty"><h3>Something lovely is on its way.</h3><p>Products will appear here soon.</p></div>'}</div></section>`;if(s.type==='categories')return `<section class="${cls}"><h2>Shop by category</h2><div class="category-list">${[...new Set(items.map(p=>p.details.category).filter(Boolean))].map(c=>`<a href="#store-products">${esc(c)} ↗</a>`).join('')||'<p>Collections coming soon.</p>'}</div></section>`;if(s.type==='about')return `<section class="${cls} about-section" id="store-about"><span class="eyebrow">OUR STORY</span><h2>A little more about us.</h2><p>${esc(d.description||'Welcome to our store. We look forward to serving you.')}</p></section>`;if(s.type==='benefits')return `<section class="${cls} store-benefits"><div>◧<h3>Cash on delivery</h3><p>Pay when your order arrives.</p></div><div>◉<h3>Order on WhatsApp</h3><p>A familiar way to shop.</p></div><div>↗<h3>Delivered to you</h3><p>${esc(d.deliveryInfo||'Contact us for delivery information.')}</p></div></section>`;if(s.type==='offers')return `<section class="${cls} offer-section"><span class="eyebrow">A LITTLE SOMETHING SPECIAL</span><h2>Discover our latest offers.</h2><p>${items.some(p=>p.details.salePrice)?'Look for special prices in our collection.':'Follow our collection for upcoming offers.'}</p><a href="#store-products" class="btn">Shop collection ↗</a></section>`;if(s.type==='reviews')return `<section class="${cls} review-section"><h2>Your experience matters.</h2><p>Shopped with us? Share your feedback on WhatsApp. Customer reviews will be added by the store owner.</p></section>`;return `<section class="${cls} contact-section"><div><h2>Let’s stay in touch.</h2><p>${esc(d.address)}</p><p>${esc(d.whatsapp)}</p>${['instagram','facebook','website'].filter(k=>d[k]).map(k=>`<a href="${esc(d[k])}" target="_blank" rel="noopener">${k} ↗</a>`).join(' ')}</div><div><h3>Delivery & returns</h3><p>Fixed delivery: ${money(d.delivery)}</p><p>${esc(d.deliveryInfo)}</p><p>${esc(d.returns||'Contact the store for returns and exchange information.')}</p></div></section>`}
function cartModal(){const subtotal=cart.reduce((n,i)=>n+(i.product.details.salePrice??i.product.details.price)*i.quantity,0);document.querySelector('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="panel modal"><div class="panel-heading"><h2>Your cart</h2><button class="icon-btn" data-action="close-modal">×</button></div>${cart.length?`<div class="cart-items">${cart.map((i,n)=>`<div class="cart-item"><div><b>${esc(i.product.details.name)}</b><small>${esc(i.size)} ${esc(i.color)}</small><span>${money(i.product.details.salePrice??i.product.details.price)}</span></div><div><button data-cart-quantity="${n}" data-delta="-1">−</button><span>${i.quantity}</span><button data-cart-quantity="${n}" data-delta="1">+</button><button class="link-btn danger" data-remove-cart="${n}">Remove</button></div></div>`).join('')}</div><div class="cart-total"><span>Subtotal <b>${money(subtotal)}</b></span><span>Delivery <b>${money(currentStore.details.delivery)}</b></span><span>Total <b>${money(subtotal+currentStore.details.delivery)}</b></span></div><form id="checkout-form">${field('Your full name','name','','text',true)}${field('Phone number','phone','','tel',true)}${area('Delivery address','address','')}<p class="muted">Payment: Cash on Delivery. Your order will be saved, then you can send it on WhatsApp.</p><div class="form-error"></div><button class="btn full" ${currentStore.status!=='approved'?'disabled':''}>${currentStore.status==='approved'?'Save order & continue to WhatsApp →':'Checkout available on approved stores only'}</button></form>`:'<div class="empty"><h3>Your cart is empty.</h3><p>Find something you love in the collection.</p></div>'}</div></div>`)}
function formValues(form){return Object.fromEntries(new FormData(form));}
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=formValues(f),button=f.querySelector('button:not([type="button"])');if(button)button.disabled=true;f.querySelector('.form-error')&&(f.querySelector('.form-error').textContent='');try{if(f.id==='home-signup-form'){sessionStorage.setItem('dd-signup-email',v.email);location.href='/signup'}if(f.id==='login-form'){const d=await api('/api/login','POST',v);location.href=d.role==='admin'?'/admin':'/dashboard'}if(f.id==='signup-form'){if(step===1){draft.email=v.email;draft.password=v.password;step++}else if(step===2){draft.slug=v.slug;draft.details={...draft.details,...v};delete draft.details.slug;step++}else if(step===3){draft.sections=readSections(f);if(!draft.sections.length)throw Error('Select at least one section.');step++}else{await api('/api/signup','POST',{...draft,subscribed:v.subscribed==='on'});draft.password='';location.href='/dashboard';return}signup();translatePublic()}if(f.id==='settings-form'){await api('/api/store','PATCH',{details:v,sections:session.store.sections});toast('Store details saved.');await dashboard()}if(f.id==='editor-form'){const selected=readSections(f),order=session.store.sections.map(x=>x.type);selected.sort((a,b)=>(order.includes(a.type)?order.indexOf(a.type):99)-(order.includes(b.type)?order.indexOf(b.type):99));selected.forEach(x=>{x.title=v['title-'+x.type]||'';x.text=v['text-'+x.type]||''});await api('/api/store','PATCH',{details:session.store.details,sections:selected});toast('Homepage saved.');await dashboard()}if(f.id==='product-form'){await api('/api/products','POST',{...v,id:editProduct,images:v.images.split('\n').map(x=>x.trim()).filter(Boolean)});document.querySelector('.modal-backdrop').remove();toast('Product saved.');await dashboard()}if(f.id==='checkout-form'){const d=await api('/api/checkout','POST',{...v,slug:currentStore.slug,items:cart.map(i=>({id:i.product.id,quantity:i.quantity,size:i.size,color:i.color}))});cart=[];document.querySelector('#cart-count').textContent='0';f.closest('.modal').innerHTML=`<div class="empty"><span>✓</span><h2>Your order is saved.</h2><p>Order #${esc(d.id.slice(0,8))} · ${money(d.total)}</p><p>Now open WhatsApp and press Send to share your order with the store.</p><a class="btn" href="${esc(d.whatsapp)}" target="_blank" rel="noopener">Open WhatsApp ↗</a><button class="btn secondary" data-action="close-modal">Continue shopping</button></div>`}}catch(error){const el=f.querySelector('.form-error');if(el)el.textContent=error.message;else toast(error.message)}finally{if(button)button.disabled=false}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-tab]');if(!el)return;try{const a=el.dataset.action;if(el.dataset.previewSection){openLayoutPreview(el.dataset.previewSection,Number(el.dataset.previewLayout));}if(el.dataset.useLayout){const type=el.dataset.useLayout,layout=Number(el.dataset.layout);const radio=document.querySelector(`[name="layout-${type}"][value="${layout}"]`);radio.checked=true;const checkbox=document.querySelector(`[name="section-${type}"]`);checkbox.checked=true;checkbox.closest('.section-option').classList.add('selected');document.querySelector('.modal-backdrop').remove();}if(a==='language'){roman=!roman;localStorage.setItem('dd-language',roman?'roman':'en');route()}if(a==='signup-back'){step--;signup();translatePublic()}if(a==='logout'){await api('/api/logout','POST',{});location.href='/'}if(a==='add-product')productModal();if(a==='close-modal')document.querySelector('.modal-backdrop')?.remove();if(a==='copy-link'){await navigator.clipboard.writeText(location.origin+'/s/'+session.store.slug);toast('Store link copied.')}if(a==='resubmit'){await api('/api/resubmit','POST',{});await dashboard()}if(el.dataset.tab){tab=el.dataset.tab;await dashboard()}if(el.dataset.editProduct)productModal(products.find(p=>p.id===el.dataset.editProduct));if(el.dataset.deleteProduct&&confirm('Delete this product? Existing orders will stay saved.')){await api('/api/products/'+el.dataset.deleteProduct,'DELETE',{});await dashboard();toast('Product deleted.')}if(el.dataset.move!==undefined){const selected=readSections(document.querySelector('#editor-form')),order=session.store.sections.map(x=>x.type);selected.sort((a,b)=>(order.includes(a.type)?order.indexOf(a.type):99)-(order.includes(b.type)?order.indexOf(b.type):99));const values=formValues(document.querySelector('#editor-form'));selected.forEach(x=>{x.title=values['title-'+x.type]||'';x.text=values['text-'+x.type]||''});const i=Number(el.dataset.move),j=i+Number(el.dataset.direction);if(j>=0&&j<selected.length){[selected[i],selected[j]]=[selected[j],selected[i]];await api('/api/store','PATCH',{details:session.store.details,sections:selected});await dashboard()}}if(el.dataset.adminId){const status=el.dataset.status,reason=status==='approved'?'':prompt('Please enter the reason:');if(reason===null)return;await api('/api/admin/stores/'+el.dataset.adminId,'PATCH',{status,reason});await admin();toast('Store status updated.')}if(el.dataset.addCart){const p=products.find(x=>x.id===el.dataset.addCart),size=document.querySelector('#size-'+p.id)?.value||'',color=document.querySelector('#color-'+p.id)?.value||'';const count=cart.filter(i=>i.product.id===p.id).reduce((n,i)=>n+i.quantity,0);if(p.details.stock!==null&&count>=p.details.stock)throw Error('No more stock available.');const existing=cart.find(i=>i.product.id===p.id&&i.size===size&&i.color===color);if(existing){if(p.details.stock!==null&&existing.quantity>=p.details.stock)throw Error('No more stock available.');existing.quantity++}else cart.push({product:p,quantity:1,size,color});document.querySelector('#cart-count').textContent=cart.reduce((n,i)=>n+i.quantity,0);toast('Added to your cart.')}if(a==='cart')cartModal();if(el.dataset.cartQuantity!==undefined){const i=cart[Number(el.dataset.cartQuantity)],q=i.quantity+Number(el.dataset.delta);if(q>100||i.product.details.stock!==null&&q>i.product.details.stock)throw Error('Quantity exceeds available stock.');if(q<1)cart.splice(Number(el.dataset.cartQuantity),1);else i.quantity=q;cartModal();document.querySelector('#cart-count').textContent=cart.reduce((n,i)=>n+i.quantity,0)}if(el.dataset.removeCart!==undefined){cart.splice(Number(el.dataset.removeCart),1);cartModal();document.querySelector('#cart-count').textContent=cart.reduce((n,i)=>n+i.quantity,0)}}catch(error){toast(error.message)}});
document.addEventListener('change',async e=>{if(e.target.name?.startsWith('section-'))e.target.closest('.section-option')?.classList.toggle('selected',e.target.checked);if(e.target.dataset.uploadTarget){const el=e.target,form=el.closest('form'),target=form.querySelector(`[name="${el.dataset.uploadTarget}"]`);try{for(const file of el.files){if(file.size>2*1024*1024)throw Error('Each image must be under 2 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});const result=await api('/api/upload','POST',{type:file.type,data});target.value=el.dataset.uploadTarget==='images'?[target.value,result.url].filter(Boolean).join('\n'):result.url}toast('Image uploaded. Save your changes to use it.')}catch(error){toast(error.message)}el.value='';}if(e.target.dataset.orderStatus){try{await api('/api/orders/'+e.target.dataset.orderStatus,'PATCH',{status:e.target.value});toast('Order status saved.')}catch(error){toast(error.message);await dashboard()}}});
document.addEventListener('input',e=>{if(e.target.name==='slug'&&document.querySelector('#slug-label'))document.querySelector('#slug-label').textContent=e.target.value});
async function route(){try{const path=location.pathname;session=await api('/api/session');if(session.user&&['/login','/signup'].includes(path)){location.replace(dashboardPath());return;}if(path==='/'){const site=await api('/api/site');if(site.slug)await storefront(site.slug);else home();}else if(path==='/signup')signup();else if(path==='/login')loginPage();else if(path==='/dashboard')await dashboard();else if(path==='/admin')await admin();else if(path==='/demo')await storefront('demo');else if(path.startsWith('/s/'))await storefront(decodeURIComponent(path.split('/')[2]));else app.innerHTML=`${nav()}<main class="empty"><h1>Page not found.</h1><a class="btn" href="/">Back to Digital Dukan</a></main>`;translatePublic()}catch(error){app.innerHTML=`${nav()}<main class="empty"><h1>We can’t open this page.</h1><p>${esc(error.message)}</p><a href="/login" class="btn">Sign in</a><a href="/" class="btn secondary">Back home</a></main>`}}
